const crypto = require('crypto');

function decryptSyncFromBase64(encryptedBase64) {
    try {
        // 使用与加密函数完全相同的密钥
        const keyBytes = [189, 48, 95, 16, 208, 255, 116, 182, 239, 84, 218, 184, 53, 181, 225, 207];
        const key = Buffer.from(keyBytes);
        const algo = `aes-${key.length * 8}-gcm`; // 确定为aes-128-gcm

        // 解码Base64数据
        const encryptedBuffer = Buffer.from(encryptedBase64, 'base64');

        // 验证总长度是否有效 (IV:12 + 密文:至少1 + 标签:16)
        if (encryptedBuffer.length < 12 + 1 + 16) {
            throw new Error('无效的加密数据长度');
        }

        // 正确提取IV、密文和标签
        const iv = encryptedBuffer.subarray(0, 12);
        console.log(iv)// 前12字节是IV
        const ciphertext = encryptedBuffer.subarray(12, -16);
        console.log(ciphertext)// 中间部分是密文
        const tag = encryptedBuffer.subarray(encryptedBuffer.length - 16); // 最后16字节是标签

        // 创建解密器并设置认证标签
        const decipher = crypto.createDecipheriv(algo, key, iv);
        decipher.setAuthTag(tag);

        // 执行解密
        const decryptedParts = [];
        decryptedParts.push(decipher.update(ciphertext, null, 'utf8'));
        decryptedParts.push(decipher.final('utf8'));

        return decryptedParts.join('');
    } catch (error) {
        console.error('解密失败:', error.message);
        throw error; // 重新抛出错误以便调用者处理
    }
}

console.log(decryptSyncFromBase64(''))